// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address caller, address to, uint256 depositAmount) public {
        vm.assume(caller != address(c));
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("migrateTo(address)", to));

        if (caller == address(this)) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
            assertEq(address(c).balance, balanceBefore);
        }
    }
}
